-- Lúdica HUB · carga dos dados do controle antigo "Lúdica Music Financeiro" para o ambiente MUSIC.
-- Rodar UMA vez no SQL Editor do Supabase, DEPOIS das migrações 0007 e 0008. Pode rodar de novo sem duplicar nada.
-- Traz: 101 lançamentos (jun/2026 a dez/2027, com as previsões), as 2 apurações da LUKA, os 4 repasses,
-- a participação (Rafa 60 / Bob 40), as regras de rateio e a Lúdica Marketing como quem cobre a falta de caixa.
-- Os arquivos dos comprovantes continuam no sistema antigo; aqui fica o nome de cada um para anexar depois.
do $$
declare
  bob uuid;
  rafa uuid;
  n int;
  partes jsonb;
begin
  select id into bob from perfis where lower(email) = 'bob@somosaludica.com';
  if bob is null or not exists (select 1 from acessos where usuario_id = bob and ambiente_id = 'music' and perfil = 'socio') then
    raise exception 'Não achei o Bob (bob@somosaludica.com) como sócio do MUSIC.';
  end if;
  select count(*), min(usuario_id::text)::uuid into n, rafa from acessos where ambiente_id = 'music' and perfil = 'socio' and usuario_id <> bob;
  if n <> 1 then
    raise exception 'Preciso de exatamente um outro sócio no MUSIC (o Rafa) e achei %. Cadastre o Rafa em Usuários como sócio do MUSIC e rode de novo.', n;
  end if;

  if not exists (select 1 from participacoes where ambiente_id = 'music') then
    insert into participacoes (ambiente_id, socio_id, percentual) values ('music', rafa, 60), ('music', bob, 40);
  end if;
  partes := jsonb_build_object(rafa::text, 60, bob::text, 40);
  update ambiente_dados
     set imposto_pct = 6, reserva_pct = 20, cobertura_socio_id = bob, cobertura_nome = 'Lúdica Marketing',
         rateios = '[{"nome": "Contas do escritório", "pct": 50}, {"nome": "Aluguel (pela metragem)", "pct": 38.022775}, {"nome": "Só Music", "pct": 100}]'::jsonb
   where ambiente_id = 'music';

  insert into lancamentos (id, ambiente_id, tipo, categoria, rubrica, descricao, mes_ref, vencimento, valor, valor_total, parte_pct, situacao, pago_em, aviso,
                           conta_origem, observacao, fora_do_fluxo, comprovante_nome, socio_id, apur_imposto_pct, apur_reserva_pct, apur_custos, apur_partes, apur_obs)
