-- Conferência com o sistema antigo. Esperado: 105 lançamentos · recebido 16800.00 · contas e custos pagos 8212.02 ·
-- repasses Rafa 5880.80 · repasses Bob 4972.80 · fora do fluxo 4942.96.
select count(*) as lancamentos,
       sum(valor) filter (where categoria = 'outras_entradas' and situacao = 'paga') as recebido,
       sum(valor) filter (where tipo = 'saida' and categoria <> 'distribuicao' and situacao = 'paga' and not fora_do_fluxo) as contas_e_custos_pagos,
       sum(valor) filter (where categoria = 'distribuicao' and socio_id <> (select id from perfis where lower(email) = 'bob@somosaludica.com')) as repasses_rafa,
       sum(valor) filter (where categoria = 'distribuicao' and socio_id = (select id from perfis where lower(email) = 'bob@somosaludica.com')) as repasses_bob,
       sum(valor) filter (where fora_do_fluxo) as fora_do_fluxo
  from lancamentos where ambiente_id = 'music';
